def lamb_candidates(N):
    result = {'initial_condition': 4/N**2, f'A monotone:x_{N},x_star': 4/N}
    result.update({f'A monotone:x_{N},y_{k}': 4/((N-k)*(N-k-1)) for k in range(N-1)})
    result.update({f'A Lipschitz:x_{k},y_{k}': 2/(N-k)**2 for k in range(N-1)})
    result[f'A Lipschitz:x_{N-1},x_{N}'] = 2
    return result

